package main
import (
    "fmt"
    "time"
    )

func out(from, to int) {
    for i:=from; i<=to; i++ {
        time.Sleep(50 * time.Millisecond)
        fmt.Println(i)
    }

}

func main() {
    // 关键字go 开启goruntine 协程
    go out(0, 5)
    go out(6, 10)
}

package main
import (
    "fmt"
    "time"
    )

func out(from, to int) {
    for i:=from; i<=to; i++ {
        time.Sleep(50 * time.Millisecond)
        fmt.Println(i)
    }

}

func main() {
    go out(0, 5)
    go out(6, 10)

    time.Sleep(500 * time.Millisecond)
}
